const trainingSet = cases.slice(0, 102);
const validationSet = cases.slice(102, 136);
const holdoutSet = cases.slice(136, 170);

const fullJson = JSON.stringify(cases, null, 2);
const holdoutJson = JSON.stringify(holdoutSet, null, 2);

const dataset_sha256 = crypto.createHash('sha256').update(fullJson).digest('hex');
const final_holdout_sha256 = crypto.createHash('sha256').update(holdoutJson).digest('hex');

const datasetMeta = {
  dataset_version: 'AG009-EVAL-001',
  total_cases: cases.length,
  training_cases: trainingSet.length,
  validation_cases: validationSet.length,
  holdout_cases: holdoutSet.length,
  dataset_sha256,
  final_holdout_sha256,
  holdout_frozen_before_execution: true,
  cases
};

const fixturesDir = path.join(__dirname, 'fixtures');
if (!fs.existsSync(fixturesDir)) {
  fs.mkdirSync(fixturesDir, { recursive: true });
}

const outputPath = path.join(fixturesDir, 'final-eval-dataset.json');
fs.writeFileSync(outputPath, JSON.stringify(datasetMeta, null, 2), 'utf-8');

console.log(`Dataset written to: ${outputPath}`);
console.log(`dataset_sha256:       ${dataset_sha256}`);
console.log(`final_holdout_sha256: ${final_holdout_sha256}`);
